attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT; if (u < 0. || u > .16){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(aO,1.); mv.xyz += normalize(-mv.xyz)*.3;
      float S = .34; mv.xy += position.xy*S; vP = position.xy*S; vU = u; vK = aK;
      gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform vec3 uCW, uCT; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      vec2 p = vP; float r = length(p), t = vU/.16, f = pow(1. - t, 1.6);
      float R = .03 + .22*(1. - pow(1. - t, 3.)), w = .006 + .008*(1. - t);
      vec3 col = mix(uCW, uCT, vK);
      float lum = exp(-pow(abs(r - R)/w, 2.4))*f*.45 + exp(-r*r*300.)*f*.4;
      vec3 outc = col*lum + mix(col, vec3(1.), .6)*lcore(r - R, w*.35)*f*.4;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

